#define PARTICLES_MIN 50.
#define PARTICLES_MAX 200.

#define duration 2.

//Explosion time
#define ExT 0.6

#define PI 3.14

vec2 hash21(float p) {
	vec3 p3 = fract(vec3(p) * vec3(.1031, .1030, .0973));
	p3 += dot(p3, p3.yzx + 33.33);
    return fract((p3.xx+p3.yz)*p3.zy);

}

vec3 hash31(float p) {
	vec3 p2 = fract(p * vec3(5.3983, 5.4427, 6.9371));
    p2 += dot(p2.zxy, p2.xyz + vec3(21.5351, 14.3137, 15.3219));
	return fract(vec3(p2.x * p2.y * 95.4337, p2.y * p2.z * 97.597, p2.z * p2.x * 93.8365));
}

vec2 dir(float id){
    vec2 h = hash21(id);
    h.y*=2.*PI;
    return h.x*vec2(cos(h.y),sin(h.y));
}


float bang(vec2 uv, float t,float id){
    float out_brightness = 0.;

    float pbrightness = pow(abs(1.-t),.5)*0.0005;
    float pcount = mix(PARTICLES_MIN,PARTICLES_MAX,fract(cos(id)));

    for(float i=0.;i<pcount;i++){
        float pid = i+.012*id;
        vec2 d = dir(pid);

        vec2 p = d*t;

        out_brightness+=pbrightness/pow(distance(uv,p),1.6);
    }
    return out_brightness;
}



float firework(vec2 uv,float t,float id){
    vec2 h = hash21(id)*2.-1.;
    h.y*=abs(h.y);
    vec2 di = vec2(h.y,sqrt(1.-h.y*h.y));
    float thrust = sqrt(min(t,ExT)/ExT);
    vec2 p = mix(vec2(0),di*thrust*duration,min(t,ExT));
    if (t<ExT) { //If hasn't exploded
        return .0002/pow(distance(uv,p),2.);
    }
    float t_bang =(t-ExT)/(1.-ExT);//Time from explosion (0-1)
    vec2 p_bang = uv-p; //Position relative to explosion
    return bang(p_bang,t_bang,id);
}


void mainImage( out vec4 fragColor, in vec2 fragCoord )
{

    vec3 col = vec3(0);
    vec2 uv = (2.*fragCoord-iResolution.xy*vec2(1.,0.))/iResolution.y;

    float time = iTime/duration;
    float id = floor(time);

    vec3 color = hash31(id);

    col+=firework(uv,fract(time),id)*color;

    fragColor = vec4(col,1.0);

}
